"""Builds practice/questions.json: 40 NPTEL 2026 assignment questions (W1-W4) + extra self-written practice."""
import json, os
Q = []
import random
def add(src, week, qno, typ, q, opts, ans, why, topic, flags=()):
    L = "ABCDEFGH"
    if src == "EXTRA" and len(opts) > 2 and not any("above" in o or "→" in o for o in opts):
        opts = list(opts); random.Random(f"{week}{qno}{q}").shuffle(opts)
    Q.append({"id": f"{src}-W{week}-Q{qno}", "src": src, "week": week, "qno": qno, "type": typ, "question": q,
              "options": [{"k": L[i], "text": t} for i, t in enumerate(opts)],
              "answer": [L[opts.index(a)] for a in ans], "explanation": why, "topics": [topic], "flags": list(flags)})
N = "NPTEL"
PH = ["Requirement Specification", "Software Design", "Software Development", "Testing", "Maintenance"]
# ---- Week 1
add(N,1,1,"MCQ","Which of the following is NOT a typical phase in the software development process?",["User Interface (UI) design","Requirements gathering","Testing","Maintenance"],["User Interface (UI) design"],"Phases: requirements, design, development, testing, maintenance.","SDLC phases")
add(N,1,2,"MCQ","Clients in software development can be ____________",["Internal users of a company","External users of a company","Other software systems","All of the above"],["All of the above"],"Clients: external users, internal to the company, or another software (e.g. Razorpay).","Clients")
add(N,1,3,"MCQ","What is the main purpose of the design phase in software development?",["To write well-documented code","To create a big-picture view of the system","To develop a user interface","To fix bugs in the code"],["To create a big-picture view of the system"],"Design gives the big-picture view and structure of the system.","Design phase")
add(N,1,4,"MCQ","How do developers typically collaborate on code in the development phase?",["Working independently all the time","Using version control systems like Git","Writing all the code in one sitting","None of the above"],["Using version control systems like Git"],"Distributed development uses tools like GitHub/Git.","Development phase")
add(N,1,5,"MCQ","What is a major drawback of the waterfall model of software development?",["It is time-consuming","It requires expensive resources","It is difficult to adapt to changing requirements","It is not suitable for large projects"],["It is difficult to adapt to changing requirements"],"Late changes cost time and money; clients may not know what they need.","Waterfall")
add(N,1,6,"MCQ","A biology research lab is developing a new computer model to simulate the growth rate of a specific bacteria strain under different environmental conditions. Who is the primary user of the model?",["An external user","Internal to the company","Another software","None of the above"],["Internal to the company"],"The lab itself uses the model: an internal client.","Clients")
add(N,1,7,"MCQ","A marketing team at a travel booking website develops a mobile app internally and conducts initial usability testing with a small group of colleagues from different departments who were not involved in development. This is an example of ___________",["Alpha testing","Beta testing","Gamma testing","Delta testing"],["Alpha testing"],"Alpha = internal employees, lab/staging. Beta = actual users in real life.","Alpha/Beta testing")
add(N,1,8,"MSQ","Which of the following statements are true?",["Description of what your functions can do without describing the implementation in detail is known as an interface","The code implemented by the interface cannot change once it has been designed","The code implemented by the interface can change once it has been designed"],["Description of what your functions can do without describing the implementation in detail is known as an interface","The code implemented by the interface can change once it has been designed"],"Implementation may change as long as the interface stays the same.","Interface")
ctx = "A bank wants to introduce a blockchain feature. Map the task to the phase of the software development process.\n\n"
for n,(t,a,w) in enumerate([("Providing the implemented blockchain feature to a few select users and checking for any errors.","Testing","Release to select users to find errors = testing."),
  ("Outlining the different modules of the new feature and how it will interact with existing features of the banking system.","Software Design","Modules and interactions = big-picture design."),
  ("Gathering information about how blockchain works and getting regulatory information from RBI.","Requirement Specification","Gathering goals/constraints = requirements."),
  ("Getting feedback about the feature from users and outlining updates for the next release.","Maintenance","Monitoring usage and planning updates = maintenance.")],9):
    add(N,1,n,"MCQ",ctx+t,PH,[a],w,"SDLC phases")
# ---- Week 2
add(N,2,1,"MCQ","What is the consequence of NOT integrating Function, Behavior, and Structure during the design phase?",["It creates an incoherent and potentially redundant design with multiple solutions.","It increases development time.","It makes the software more complex.","It is difficult to communicate the design to stakeholders."],["It creates an incoherent and potentially redundant design with multiple solutions."],"E.g. only mood detection as a function: many possible solutions, not decidable.","FBS integration")
add(N,2,2,"MSQ","What are the advantages of integrating Function, Behavior, and Structure during conceptual design?",["It creates a unified view of the design solution.","It helps ensure the solution meets all the requirements.","It facilitates clear communication within the development team.","It reduces the risk of getting stuck during the design process."],["It creates a unified view of the design solution.","It helps ensure the solution meets all the requirements.","It facilitates clear communication within the development team.","It reduces the risk of getting stuck during the design process."],"All four benefits were listed in Lecture 11.","FBS integration")
add(N,2,3,"MCQ","How many possible FBS graphs can exist for a single software design problem?",["There is always a single, correct FBS graph.","There can be multiple possible FBS graphs depending on the design approach."],["There can be multiple possible FBS graphs depending on the design approach."],"BSF, FSB and other combinations are all possible.","FBS graph")
add(N,2,4,"MCQ","In __________, you can explore the graph and then edit the graph by adding the features available in Think&Link.",["Planning Phase","Introduction Phase","Induction Phase","Brainstorm Phase"],["Induction Phase"],"Introduction: explore only. Induction: explore and edit, then evaluate. Ideation: build from scratch.","Think & Link")
add(N,2,5,"MCQ","The formal realisation evaluation criteria in a FBS graph ensures that _________",["FBS graph can be used for formal documentation","FBS graph is formally correct","FBS graph can be used in formal conversations","FBS graph converts to the corresponding UML diagrams"],["FBS graph converts to the corresponding UML diagrams"],"Formal realisation = the graph can be translated to UML.","Evaluation criteria")
add(N,2,6,"MCQ","The most important reason to link function, structure and behaviour is to _________",["Describe in depth a part of a solution","Create a correct solution","Develop an integrated solution","Create different solutions for a given problem"],["Develop an integrated solution"],"Linking gives an integrated view of the design.","FBS integration")
add(N,2,7,"MSQ","Consider: \"The emotion camera captures the user emotion, then provides it to the playlist generator which then creates a playlist based on the mood\". This statement describes ____________",["interactions in the design solution","implementation of the mood based music playing feature","description of a use case"],["interactions in the design solution","implementation of the mood based music playing feature"],"It is a behaviour (interaction of structures). The portal gave partial credit for either one; the accepted key lists both.","Behaviour",["portal-partial-credit"])
add(N,2,8,"MCQ","The __________ evaluation criteria is indicative of the interconnected function, structure and behaviour nodes in the FBS graph.",["Consistency","Complexity","Connectivity","Competency"],["Connectivity"],"Connectivity = how F, S, B nodes are interlinked.","Evaluation criteria")
add(N,2,9,"MCQ","The _________ evaluation criteria is indicative of the number of nodes in each of the categories of function, behaviour and structure.",["Complexity","Level adjacency","Validity","Correctness"],["Complexity"],"Complexity = number of nodes per category.","Evaluation criteria")
add(N,2,10,"MCQ","The stage which precedes the development stage in the traditional SDLC is?",["Requirement stage","Design stage","Maintenance stage","Testing stage"],["Design stage"],"Requirements → Design → Development → Testing → Maintenance.","SDLC phases")
# ---- Week 3
add(N,3,1,"MCQ","What are the two main types of views used in UML diagrams to represent a software design?",["Sequential view and logical view","Structural view and dynamic behavioral view","Abstract view and concrete view","Functional view and non-functional view"],["Structural view and dynamic behavioral view"],"Class diagram = structural; sequence/state/activity = dynamic.","UML")
add(N,3,2,"MCQ","What is design tracing in the context of VeriSIM?",["Analyzing the comments and code annotations left by developers.","Constructing a state diagram that models a specific scenario in the software design.","Manually reviewing the class diagram for errors and inconsistencies.","Stepping through the code line by line to identify bugs."],["Constructing a state diagram that models a specific scenario in the software design."],"Transitions come from sequence-diagram messages; state variables from the class diagram.","VeriSIM")
add(N,3,3,"MCQ","What is the main difference between functional requirements and non-functional requirements according to the lecture?",["Functional requirements define what the system should do, while non-functional requirements define how the system should look.","Functional requirements are easier to define, while non-functional requirements are more subjective.","Functional requirements focus on the system's features, while non-functional requirements focus on its behavior.","Functional requirements are provided by the developers, while non-functional requirements come from the users."],["Functional requirements focus on the system's features, while non-functional requirements focus on its behavior."],"Functional = what the system does; non-functional = how it behaves.","Quality attributes")
rido = "Rido is a ride sharing app, where users can share rides with others to reach their destination.\n\n"
add(N,3,4,"MCQ",rido+"Consider the requirement: \"When users pay for their rides (UPI, Net banking, mobile wallets etc.), payment failures can occur. Rido should be able to seamlessly handle such failures.\" This is a quality attribute related to __________",["Correctness","Reliability","Robustness","None of the above"],["Robustness"],"Robustness = recovering from errors/unexpected situations.","Quality attributes")
add(N,3,5,"MCQ",rido+"During beta testing, Rido crashed often when many users tried to book rides. Rido is unable to satisfy the requirement of ___________",["Correctness","Reliability","Robustness","None of the above"],["Reliability"],"Reliability = behaving the same way over time; crashing often breaks it.","Quality attributes")
atm = "ATM withdrawal system (class diagram with ATM and Account classes, and a sequence diagram for withdrawal).\n\n"
add(N,3,6,"MCQ",atm+"The class diagram only contains data members in the class and it has nothing to do with the behavior of the class.",["True","False"],["False"],"Classes have three compartments: name, attributes, operations (methods).","Class diagram",["diagram-not-in-source"])
add(N,3,7,"MCQ",atm+"\"balance\" in the \"Account\" class in the class diagram is _____________",["A class","An object","A data member of the \"Account\" class","A member function of the \"Account\" class"],["A data member of the \"Account\" class"],"Attributes sit in the middle compartment.","Class diagram",["diagram-not-in-source"])
add(N,3,8,"MCQ",atm+"\"setOption()\" in the ATM class in the class diagram is _____________",["A class","An object","A data member of the \"ATM\" class","A member function of the \"ATM\" class"],["A member function of the \"ATM\" class"],"Operations sit in the bottom compartment.","Class diagram",["diagram-not-in-source"])
add(N,3,9,"MCQ",atm+"What are the possible values that the \"deposit()\" function of the \"Account\" class returns?",["True or False","1 or 0","Deposited amount","Depositor name"],["True or False"],"Return type is bool in the class diagram.","Class diagram",["diagram-not-in-source"])
add(N,3,10,"MCQ",atm+"If checkPin() function from the ATM class returns false then what message will it show to the user?",["Low account balance","Correct PIN","Incorrect PIN","Re-enter PIN"],["Incorrect PIN"],"Read off the else-branch of the sequence diagram.","Sequence diagram",["diagram-not-in-source"])
# ---- Week 4
add(N,4,1,"MCQ","What do the structures in the FBS framework represent?",["The functionalities and features of the software.","The physical and logical components that make up the software.","The interactions between different functionalities.","The user interface elements of the software."],["The physical and logical components that make up the software."],"F = features, S = components, B = interactions.","FBS")
add(N,4,2,"MCQ","What is the key difference between the FBS and UML modelling representations?",["FBS focuses on user interface design, while UML focuses on system functionalities.","FBS is used for code generation, while UML is for design communication.","FBS provides a high-level overview, while UML diagrams offer more detailed views.","FBS is created before requirements definition, while UML comes after."],["FBS provides a high-level overview, while UML diagrams offer more detailed views."],"Different levels of abstraction.","Abstraction")
add(N,4,3,"MSQ","Purpose of the modeling is _________",["To provide a vehicle for communication and idea generation","To do analysis and comprehension","To get hold of stakeholders and gather requirements","To come up with a blueprint for implementation"],["To provide a vehicle for communication and idea generation","To do analysis and comprehension","To come up with a blueprint for implementation"],"FBS: communication; UML: analysis; detailed UML: blueprint.","Modelling")
add(N,4,4,"MCQ","If a team of software designers want to first communicate the key ideas of the software before detailing out the solution, the appropriate model to be used is __________",["FBS","Simple UML models","Detailed UML models"],["FBS"],"FBS = high-level overview for communication.","Modelling")
add(N,4,5,"MCQ","A software design team wants a model which a development team can directly transform to code. Which is most appropriate?",["FBS","Simple UML models","Detailed UML models"],["Detailed UML models"],"Detailed UML maps closely to code; tools can generate code.","Modelling")
add(N,4,6,"MCQ","__________ is used to divide a software system into multiple independent modules, which are capable of carrying out the desired functionalities.",["Abstraction","Modularization","Decomposition"],["Modularization"],"Modularization = independent co-working modules.","Abstraction")
add(N,4,7,"MCQ","__________ is a way of hiding details in the design at each stage of the design process.",["Abstraction","Modularization","Decomposition"],["Abstraction"],"Abstraction hides details; level of detail = level of abstraction.","Abstraction")
add(N,4,8,"MCQ","While creating a software conceptual design, you are breaking down the implementation components. Which software engineering process are you following?",["Design analysis","Testing","Decomposition","Implementation"],["Decomposition"],"Breaking down components = decomposition.","Abstraction")
